#!/usr/bin/env bash
# AUTO-GENERATED by gen/gen_workloads.py — PR #12583. Fetch-on-demand weights for cluster mixtral.
# SAFE: nothing downloads unless you RUN this on the target box. Skips if cached.
# Shared cache: <repo>/.weights/mixtral (gitignored, reused across the cluster's PRs).
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
CACHE="$(cd "$HERE/../../../.." && pwd)/.weights/mixtral"
HF_ID="mistralai/Mixtral-8x7B-Instruct-v0.1"
SIZE="~90GB"
if [ "${ALLOW_MIXTRAL:-0}" != "1" ]; then
  echo "# mixtral REFUSED: ~90GB. Re-run with ALLOW_MIXTRAL=1 on a box that can hold it."; exit 0
fi
if [ -d "$CACHE" ] && [ -n "$(ls -A "$CACHE" 2>/dev/null)" ]; then
  echo "# mixtral: cache HIT at $CACHE — skip download."; exit 0
fi
mkdir -p "$CACHE"
echo "# mixtral: downloading $HF_ID ($SIZE) -> $CACHE"
python3 - "$HF_ID" "$CACHE" <<'PY'
import sys
from huggingface_hub import snapshot_download
snapshot_download(repo_id=sys.argv[1], local_dir=sys.argv[2],
                  local_dir_use_symlinks=False, resume_download=True)
print("done")
PY

echo "# mixtral: ready at $CACHE"
